parameters.jsCode:
// De aanbieders waarvan LaVega de voorwaarden moet kennen.
// `provider` MOET exact overeenkomen met wat LaVega toont: bank + "betaalpas"
// of "creditcard" (zie productOf() in packages/core/src/travel.ts).
// `url` is de eigen tarievenpagina van de aanbieder — dat is precies de stap
// die de zoek-agent onbetrouwbaar maakte. Controleer een URL als een aanbieder
// leeg blijft; die veranderen af en toe.
return [
  { json: { provider: 'Revolut betaalpas',           url: 'https://www.revolut.com/nl-NL/legal/fees/' } },
  { json: { provider: 'ING betaalpas',               url: 'https://www.ing.nl/particulier/betalen/betalen-en-geld-opnemen-in-het-buitenland' } },
  { json: { provider: 'ING creditcard',              url: 'https://www.ing.nl/particulier/betalen/creditcard/kosten-creditcard' } },
  { json: { provider: 'ABN AMRO betaalpas',          url: 'https://www.abnamro.nl/nl/prive/betalen/in-het-buitenland/index.html' } },
  { json: { provider: 'ABN AMRO creditcard',         url: 'https://www.abnamro.nl/nl/prive/creditcards/tarieven.html' } },
  { json: { provider: 'American Express creditcard', url: 'https://www.americanexpress.com/nl-nl/kaarten/alle-kaarten/' } },
  { json: { provider: 'bunq betaalpas',              url: 'https://www.bunq.com/nl/pricing' } },
  { json: { provider: 'Trading 212 creditcard',      url: 'https://www.trading212.com/nl/terms/card' } },
];

// HTML -> platte tekst. Het model hoeft geen opmaak te zien, en een kale
// pagina scheelt tokens en tijd. Alles boven 18k tekens gaat eraf: tarieven
// staan vrijwel altijd in het eerste deel, en een lange staart aan footer-
// en cookieteksten helpt niet.
const out = [];
for (const item of $input.all()) {
  const provider = item.json.provider;
  const url = item.json.url;
  const raw = typeof item.json.data === 'string' ? item.json.data : '';
  if (!raw) { out.push({ json: { provider, url, text: '', ok: false } }); continue; }
  const text = raw
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 18000);
  out.push({ json: { provider, url, text, ok: text.length > 200 } });
}
return out;

